S = "Hakeem Force Academy"
QS = [
(S, "Who is the Prime Minister of Israel?", ["Naftali Bennett", "Yair Lapid", "Benjamin Netanyahu", "Benny Gantz"], 2,
 "Benjamin Netanyahu has been Prime Minister of Israel since December 2022 and was still in office in October 2026.",
 "Naftali Bennett (2021-2022) was PM when candidates wrote in 2022, and Israel's next general election is scheduled for 27 October 2026.", [94]),
(S, "In which year was Pakistan's first postage stamp issued?", ["1947", "1948", "1949", "1950"], 1,
 "Pakistan issued its first set of four postage stamps on 9 July 1948.",
 "Before that, stamps of British India overprinted with the word Pakistan were used in 1947.", [4224, 2728, 2748]),
(S, "If the National Assembly and the Senate disagree on a bill, who resolves the issue under the Constitution of Pakistan?", ["The Supreme Court", "A joint sitting of both Houses of Parliament", "The President alone", "The Federal Shariat Court"], 1,
 "Under Article 70 of the 1973 Constitution, a disputed bill is put before a joint sitting of both Houses and is passed by a majority of the total members present and voting.",
 "The joint sitting is summoned by the President.", [4256]),
(S, "What is the capital of Italy?", ["Milan", "Rome", "Venice", "Naples"], 1,
 "Rome is the capital and largest city of Italy.",
 "Vatican City, the smallest country in the world, lies inside Rome.", [3521]),
(S, "Who is the President of Italy?", ["Giorgio Napolitano", "Giorgia Meloni", "Mario Draghi", "Sergio Mattarella"], 3,
 "Sergio Mattarella has been President of Italy since 2015 and was re-elected for a second term in 2022.",
 "Giorgia Meloni is the Prime Minister of Italy, not the President.", [3831]),
(S, "Where is Jabal Arafat (Jabal-e-Rahmat), the hill where pilgrims stand on 9 Dhul Hijjah?", ["Near Makkah, in the plain of Arafat", "In Madina", "In Taif", "In Jeddah"], 0,
 "Jabal Arafat, also called Jabal-e-Rahmat, stands in the plain of Arafat about 20 km southeast of Makkah.",
 "Standing at Arafat on 9 Dhul Hijjah is the most important rite (rukn) of Hajj.", [4339, 4340]),
(S, "Where is Jannat-ul-Mualla (Jannatul Mula), the famous graveyard?", ["Madina", "Karbala", "Makkah", "Jerusalem"], 2,
 "Jannat-ul-Mualla is the historic cemetery of Makkah, where Hazrat Khadijah (RA) is buried.",
 "The famous graveyard of Madina is Jannat-ul-Baqi.", [4345]),
(S, "Who is the angel in charge of Jahannam (Hell), often called its keeper?", ["Israfeel", "Malik", "Mikaeel", "Ridwan"], 1,
 "Malik is the angel appointed as the keeper (Daroga) of Jahannam, and he is mentioned in Surah Az-Zukhruf.",
 "Ridwan is the angel who is the keeper of Jannah.", [3810, 5102, 3816, 4410, 5143]),
(S, "Jami at-Tirmidhi is a famous book of what?", ["Hadith", "Fiqh", "Quran commentary", "Islamic history"], 0,
 "Jami at-Tirmidhi is a collection of hadith compiled by Imam Tirmidhi.",
 "It is counted among the Sihah Sittah, the six authentic books of hadith.", [2804]),
(S, "How many Muslims were martyred in the Battle of Uhud?", ["14", "50", "70", "313"], 2,
 "About 70 Muslims were martyred at Uhud, including Hazrat Hamza (RA).",
 "In the Battle of Badr only 14 Muslims were martyred.", [2184]),
(S, "How many gates does Jannah (Paradise) have?", ["Four", "Seven", "Eight", "Ten"], 2,
 "According to authentic hadith, Jannah has eight gates, one of which is Ar-Rayyan for those who fast.",
 "Jahannam, by contrast, has seven gates.", [840, 841]),
(S, "Which of the following is a member of SAARC?", ["Iran", "Afghanistan", "Japan", "China"], 1,
 "Afghanistan joined SAARC in 2007 as its eighth member, while Iran, Japan and China are only observers.",
 "The other members are Pakistan, India, Bangladesh, Nepal, Bhutan, Sri Lanka and the Maldives.", [4762]),
(S, "Who is the Prime Minister of Japan?", ["Fumio Kishida", "Sanae Takaichi", "Shinzo Abe", "Shigeru Ishiba"], 1,
 "Sanae Takaichi became Japan's first woman Prime Minister in October 2025 and was re-designated after the February 2026 election.",
 "Japan has no president; its head of state is Emperor Naruhito, and Fumio Kishida was PM in 2022.", [128, 129, 5139]),
(S, "Which fighter jet has Pakistan produced jointly with China?", ["JF-17 Thunder", "F-16 Fighting Falcon", "Mirage III", "J-7"], 0,
 "The JF-17 Thunder is a light multirole fighter built by Pakistan Aeronautical Complex, Kamra, with China's Chengdu Aircraft Corporation.",
 "Its Chinese designation is FC-1 Xiaolong.", [4582, 4583, 4692]),
(S, "How many Jewish tribes lived in Madina when the Holy Prophet (SAW) migrated there?", ["Two", "Three", "Five", "Seven"], 1,
 "The three main Jewish tribes of Madina were Banu Qaynuqa, Banu Nadir and Banu Quraizah.",
 "The Charter of Madina (Misaq-e-Madina) was made with them after the Hijrah.", [2174, 2175, 2277]),
(S, "Banu Quraizah, a tribe of Madina, belonged to which religion?", ["Islam", "Christianity", "Judaism", "Idol worship"], 2,
 "Banu Quraizah was a Jewish tribe of Madina.",
 "They broke their pact during the Battle of Khandaq (Ahzab).", [3145]),
(S, "Who wrote the famous biography 'Jinnah of Pakistan'?", ["Fatima Jinnah", "Stanley Wolpert", "Hector Bolitho", "Liaquat Ali Khan"], 1,
 "Stanley Wolpert, an American historian, wrote 'Jinnah of Pakistan' in 1984.",
 "Fatima Jinnah wrote 'My Brother' and Hector Bolitho wrote 'Jinnah: Creator of Pakistan'.", [1477, 1480]),
(S, "Change into passive voice: He said, \"I have done my job.\"", ["It was said by him that his job had been done by him.", "It was said by him that he had done his job.", "His job was done by him.", "It is said by him that I have done my job."], 0,
 "In indirect passive form the statement becomes: It was said by him that his job had been done by him.",
 "In reported speech, the present perfect changes to the past perfect after a past tense reporting verb.", [791]),
(S, "Change the narration: He says, \"I did not care about my job.\"", ["He says that he had not cared about his job.", "He said that he did not care about his job.", "He says that he did not care about his job.", "He says that I did not care about my job."], 2,
 "The reporting verb says is in the present tense, so the tense of the reported speech does not change; only the pronouns change.",
 "If the reporting verb were past (said), the verb inside would shift back to the past perfect.", [794]),
(S, "Fill in the blank: ____ MA degree is requisite to get a job.", ["A", "An", "The", "No article"], 1,
 "MA is pronounced em-ay, which begins with a vowel sound, so the article an is used.",
 "The article depends on the sound, not the spelling, as in an hour and a university.", [1946]),
(S, "Which was the first princely state to accede to Pakistan?", ["Kalat", "Swat", "Bahawalpur", "Hunza"], 2,
 "Bahawalpur was the first princely state to accede to Pakistan, in October 1947.",
 "Its ruler, the Nawab Sadiq Muhammad Khan Abbasi V, acceded on 5 October 1947.", [4961, 1371]),
(S, "Which defence organization did Pakistan join in 1954?", ["CENTO", "SEATO", "NATO", "Warsaw Pact"], 1,
 "Pakistan joined the South East Asia Treaty Organization (SEATO) in September 1954.",
 "Pakistan joined the Baghdad Pact, later CENTO, in 1955.", [4789]),
(S, "A. R. Cornelius, a Chief Justice of Pakistan, belonged to which religion?", ["Islam", "Hinduism", "Christianity", "Sikhism"], 2,
 "Justice Alvin Robert Cornelius was a Christian and served as Chief Justice of Pakistan from 1960 to 1968.",
 "He was known for his integrity and simple lifestyle.", [1665]),
(S, "According to hadith, about which act will a person be questioned first on the Day of Judgment in matters of worship?", ["Zakat", "Fasting", "Hajj", "Salah"], 3,
 "The Prophet (SAW) said the first deed for which a servant will be called to account is his prayer (Salah).",
 "Among matters between people, the first judgment will be about bloodshed.", [2870]),
(S, "In which Hijri year was Abu Jahl killed?", ["1 AH", "2 AH", "3 AH", "8 AH"], 1,
 "Abu Jahl was killed in the Battle of Badr, which took place in Ramadan 2 AH.",
 "He was killed by two young Ansari brothers, Muadh and Muawwidh.", [2611]),
(S, "How many times did Jansher Khan win the World Open squash title?", ["4", "6", "8", "10"], 2,
 "Jansher Khan won the World Open squash championship eight times between 1987 and 1996.",
 "He also won the British Open six times, while Jahangir Khan won the World Open six times.", [2262, 2265, 2263, 858]),
]
